CREATE TYPE "OrderStatus" AS ENUM ('PENDING','CONFIRMED','PROCESSING','SHIPPED','DELIVERED','CANCELLED');
CREATE TYPE "PaymentStatus" AS ENUM ('PENDING','PAID','FAILED','REFUNDED');
CREATE TYPE "PaymentMethod" AS ENUM ('COD','RAZORPAY');
CREATE TABLE "Product" ("id" TEXT NOT NULL,"slug" TEXT NOT NULL,"name" TEXT NOT NULL,"category" TEXT NOT NULL,"description" TEXT NOT NULL,"dimensions" TEXT NOT NULL,"pricePaise" INTEGER NOT NULL,"compareAtPaise" INTEGER,"imageUrl" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"stock" INTEGER NOT NULL DEFAULT 0,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Product_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Customer" ("id" TEXT NOT NULL,"firebaseUid" TEXT NOT NULL,"email" TEXT,"name" TEXT,"phone" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Customer_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Order" ("id" TEXT NOT NULL,"orderNumber" TEXT NOT NULL,"customerId" TEXT NOT NULL,"status" "OrderStatus" NOT NULL DEFAULT 'PENDING',"paymentStatus" "PaymentStatus" NOT NULL DEFAULT 'PENDING',"paymentMethod" "PaymentMethod" NOT NULL,"paymentProviderId" TEXT,"subtotalPaise" INTEGER NOT NULL,"shippingPaise" INTEGER NOT NULL,"totalPaise" INTEGER NOT NULL,"currency" TEXT NOT NULL DEFAULT 'INR',"recipientName" TEXT NOT NULL,"phone" TEXT NOT NULL,"addressLine1" TEXT NOT NULL,"addressLine2" TEXT,"city" TEXT NOT NULL,"state" TEXT NOT NULL,"postalCode" TEXT NOT NULL,"notes" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Order_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OrderItem" ("id" TEXT NOT NULL,"orderId" TEXT NOT NULL,"productId" TEXT NOT NULL,"productName" TEXT NOT NULL,"unitPricePaise" INTEGER NOT NULL,"quantity" INTEGER NOT NULL,"lineTotalPaise" INTEGER NOT NULL,CONSTRAINT "OrderItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "ProcessedWebhook" ("id" TEXT NOT NULL,"provider" TEXT NOT NULL,"eventId" TEXT NOT NULL,"processedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ProcessedWebhook_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Product_slug_key" ON "Product"("slug");
CREATE INDEX "Product_category_active_idx" ON "Product"("category","active");
CREATE INDEX "Product_active_createdAt_idx" ON "Product"("active","createdAt");
CREATE UNIQUE INDEX "Customer_firebaseUid_key" ON "Customer"("firebaseUid");
CREATE INDEX "Customer_email_idx" ON "Customer"("email");
CREATE UNIQUE INDEX "Order_orderNumber_key" ON "Order"("orderNumber");
CREATE UNIQUE INDEX "Order_paymentProviderId_key" ON "Order"("paymentProviderId");
CREATE INDEX "Order_customerId_createdAt_idx" ON "Order"("customerId","createdAt");
CREATE INDEX "Order_status_createdAt_idx" ON "Order"("status","createdAt");
CREATE INDEX "OrderItem_orderId_idx" ON "OrderItem"("orderId");
CREATE UNIQUE INDEX "ProcessedWebhook_eventId_key" ON "ProcessedWebhook"("eventId");
ALTER TABLE "Order" ADD CONSTRAINT "Order_customerId_fkey" FOREIGN KEY ("customerId") REFERENCES "Customer"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_orderId_fkey" FOREIGN KEY ("orderId") REFERENCES "Order"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "OrderItem" ADD CONSTRAINT "OrderItem_productId_fkey" FOREIGN KEY ("productId") REFERENCES "Product"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
